function openDestinoAlmacen(id){var s=state.seriales.find(function(x){return String(x.id)===String(id);}); if(!s)return; var opts=state.almacenes.filter(function(a){return !isTallerAlmacenId(idOf(a));}).map(function(a){return '<option value="'+esc(idOf(a))+'">'+esc(a.nombre||a.codigo)+'</option>';}).join(''); var div=document.createElement('div'); div.className='taller-v2-modal-backdrop'; div.id='tallerV2ModalBackdrop'; div.innerHTML='<div class="taller-v2-modal"><div class="taller-v2-modal-head"><h3>Transferir equipo reparado</h3><button class="taller-v2-btn gray" onclick="document.getElementById(\'tallerV2ModalBackdrop\').remove()">Cerrar</button></div><div class="taller-v2-modal-body"><p>Esta acción registrará una <b>transferencia</b>, no una salida del sistema.</p><div class="taller-v2-form-grid"><div class="taller-v2-field"><label>Equipo</label><input readonly value="'+esc(pName(prodId(s))+' · '+serialCode(s))+'"></div><div class="taller-v2-field"><label>Almacén destino</label><select id="tallerV2DestinoAlmacen">'+opts+'</select></div><div class="taller-v2-field full"><label>Observación</label><textarea id="tallerV2SalidaObs" rows="3" placeholder="Observación opcional de la transferencia"></textarea></div></div></div><div class="taller-v2-confirm-actions"><button class="taller-v2-btn gray" onclick="document.getElementById(\'tallerV2ModalBackdrop\').remove()">Cancelar</button><button class="taller-v2-btn success" onclick="lotekaTallerV2ConfirmarEnvio(\''+esc(id)+'\')">Confirmar transferencia</button></div></div>'; document.body.appendChild(div);}
