async function confirmarBaja(id){var s=state.seriales.find(function(x){return String(x.id)===String(id);}); if(!s)return; var obs=txt(document.getElementById('tallerV2BajaObs')&&document.getElementById('tallerV2BajaObs').value)||'No reparable'; try{var newObs=withTallerObs(s.observaciones,'Baja','Baja desde Taller. '+obs); var updated=await updateSerial(id,{estado:'Baja',ubicacion_tipo:'BAJA',almacen_id:null,agencia_id:null,grupo_id:null,observaciones:newObs,actualizado_por:userId()}); Object.assign(s,updated||{},{estado:'Baja',almacen_id:null,observaciones:newObs}); var mv=await createMovement({tipo_movimiento:'Despacho',serial_id:id,producto_id:prodId(s),origen_tipo:'ALMACEN',origen_id:tallerAlmacen()?idOf(tallerAlmacen()):null,origen_nombre:'Almacén Taller',destino_tipo:'BAJA',destino_id:null,destino_nombre:'Salida del sistema',cantidad:1,motivo:'Baja / salida del sistema',observaciones:'Baja de equipo no reparable desde Taller. Serial: '+serialCode(s)+' · '+obs,creado_por:userId(),usuario_nombre:userName(),creado_en:nowISO()}); state.movimientos.unshift(mv); await notify({modulo:'TALLER',tipo:'TALLER_BAJA',titulo:'Equipo dado de baja',mensaje:serialCode(s)+' salió del inventario activo',importancia:'alta',usuario_nombre:userName()}); var modal=document.getElementById('tallerV2ModalBackdrop'); if(modal)modal.remove(); renderAll();}catch(e){alert('No se pudo dar de baja: '+(e.message||e));}}
function abrirConsumo(id){var s=state.seriales.find(function(x){return String(x.id)===String(id);}); if(!s)return; var cs=consumiblesStock(); var opts=cs.length?cs.map(function(c){return '<option value="'+esc(c.producto_id)+'">'+esc(c.nombre)+' · Disponible: '+c.cantidad+'</option>';}).join(''):'<option value="">No hay consumibles disponibles en ALM-TALLER</option>'; var old=document.getElementById('tallerV2ModalBackdrop'); if(old)old.remove(); var div=document.createElement('div'); div.className='taller-v2-modal-backdrop'; div.id='tallerV2ModalBackdrop'; div.innerHTML='<div class="taller-v2-modal taller-v2-action-modal"><div class="taller-v2-modal-head"><h3><i class="fas fa-screwdriver-wrench"></i> Registrar consumo interno</h3><button class="taller-v2-btn gray" onclick="document.getElementById(\'tallerV2ModalBackdrop\').remove()">Cerrar</button></div><div class="taller-v2-modal-body"><div class="taller-v2-exp-head"><div><span>Equipo</span><strong>'+esc(pName(prodId(s)))+'</strong></div><div><span>Serial</span><strong>'+esc(serialCode(s))+'</strong></div><div><span>Origen del consumo</span><strong>ALM-TALLER</strong></div><div><span>Tipo</span><strong>Salida por consumo interno</strong></div></div><div class="taller-v2-exp-note"><b>Selecciona el consumible usado en esta reparación.</b><br>El sistema registrará el movimiento como salida por consumo interno y lo vinculará al expediente del serial.</div><div class="taller-v2-form-grid"><div class="taller-v2-field"><label>Consumible</label><select id="tallerV2ConsumoProducto">'+opts+'</select></div><div class="taller-v2-field"><label>Cantidad</label><input id="tallerV2ConsumoCantidad" type="number" min="1" value="1"></div><div class="taller-v2-field full"><label>Observación del consumo</label><textarea id="tallerV2ConsumoObs" rows="3" placeholder="Ejemplo: se utilizó rodillo por desgaste..."></textarea></div></div></div><div class="taller-v2-confirm-actions"><button class="taller-v2-btn gray" onclick="document.getElementById(\'tallerV2ModalBackdrop\').remove()">Cancelar</button><button class="taller-v2-btn success" '+(cs.length?'':'disabled')+' onclick="lotekaTallerV2ConfirmarConsumo(\''+esc(id)+'\')">Guardar consumo</button></div></div>'; document.body.appendChild(div);}
